-- Dataset: jogadores de uma plataforma de jogos online (dados sintéticos).
-- SQL padrão: funciona em H2, PostgreSQL, MySQL e SQLite.
-- Cada comando termina em ';' e ocupa uma única linha.

DROP TABLE IF EXISTS jogador;
CREATE TABLE jogador (id INT PRIMARY KEY, apelido VARCHAR(40) NOT NULL, horas_semana DOUBLE PRECISION NOT NULL, partidas_semana INT NOT NULL, gasto_mensal DOUBLE PRECISION NOT NULL, taxa_vitoria DOUBLE PRECISION NOT NULL, perfil VARCHAR(20) NOT NULL);
